import{_ as c,o,c as d,a8 as a}from"./chunks/framework.CiGKN4gy.js";const s=JSON.parse('{"title":"跨版本升级","description":"","frontmatter":{"title":"跨版本升级","lang":"zh-CN"},"headers":[],"relativePath":"zh-cn/advance/upgrade.md","filePath":"zh-cn/advance/upgrade.md","lastUpdated":1790354326000}'),l={name:"zh-cn/advance/upgrade.md"};function i(t,e,x,r,n,h){return o(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"base64:JTdCJTIydGl0bGUlMjIlM0ElMjIlRTglQjclQTglRTclODklODglRTYlOUMlQUMlRTUlOEQlODclRTclQkElQTclMjIlMkMlMjJsYW5nJTIyJTNBJTIyemgtQ04lMjIlMkMlMjJkYXRlJTIyJTNBMTc5MDM1NDMyNjAwMCU3RA=="},[...e[0]||(e[0]=[a('<h1 id="跨版本升级" tabindex="-1">跨版本升级 <a class="header-anchor" href="#跨版本升级" aria-label="Permalink to &quot;跨版本升级&quot;">​</a></h1><p>升级模块均需要按照<a href="/ngx_waf-docs/zh-cn/guide/installation.html">安装指南</a>中的说明重新安装。</p><h2 id="从-9-x-x-升级到-10-x-x" tabindex="-1">从 <code>9.x.x</code> 升级到 <code>10.x.x</code> <a class="header-anchor" href="#从-9-x-x-升级到-10-x-x" aria-label="Permalink to &quot;从 `9.x.x` 升级到 `10.x.x`&quot;">​</a></h2><ol><li>如果你使用了指令 <code>waf_http_status</code>，请根据文档将其替换为指令 <code>waf_action</code>。</li><li>如果你设置了指令 <code>waf_cc_deny</code> 的参数 <code>size</code>，你应该根据文档使用参数 <code>zone</code> 来替代。</li><li>如果你使用了指令 <code>waf_cc_deny</code> 的参数 <code>CAPTCHA</code>，你应该根据文档使用指令 <code>waf_action</code> 来替代。</li></ol><h2 id="从-8-x-x-升级到-9-x-x" tabindex="-1">从 <code>8.x.x</code> 升级到 <code>9.x.x</code> <a class="header-anchor" href="#从-8-x-x-升级到-9-x-x" aria-label="Permalink to &quot;从 `8.x.x` 升级到 `9.x.x`&quot;">​</a></h2><ol><li>安装 <a href="https://github.com/SpiderLabs/ModSecurity" target="_blank" rel="noreferrer">libmodsecurity</a> 的动态链接库和头文件。</li><li>在项目根目录下运行命令 <code>git clone -b v2.3.0 https://github.com/troydhanson/uthash.git lib/uthash</code>。</li><li>指令 <code>waf_mode</code> 的一些参数被删除，如果你使用了这些参数请删除。 <ul><li>LIBINJECTION</li><li>LIBINJECTION-SQLI</li><li>LIBINJECTION-XSS</li><li>ADV</li></ul></li><li>删除高级规则的文件 <code>advanced</code>。</li><li>指令 <code>waf_priority</code> 的参数 <code>ADV</code> 被删除，如果你使用了此参数请删除。</li><li>为指令 <code>waf_priority</code> 新增了一个参数 <code>MODSECURITY</code>，如果你使用了此指令请将改参数填写到合适的位置。</li></ol><h2 id="从-7-x-x-升级到-8-x-x" tabindex="-1">从 <code>7.x.x</code> 升级到 <code>8.x.x</code> <a class="header-anchor" href="#从-7-x-x-升级到-8-x-x" aria-label="Permalink to &quot;从 `7.x.x` 升级到 `8.x.x`&quot;">​</a></h2><ol><li>安装 <code>libcurl</code> 的动态链接库和头文件。</li><li>在项目根目录下运行命令 <code>git clone https://github.com/DaveGamble/cJSON.git lib/cjson</code>。</li><li>在项目根目录下运行命令 <code>git clone https://github.com/libinjection/libinjection.git lib/libinjection</code>。</li><li>如果你使用了指令 <code>waf_mode</code> 并且使用了该指令的参数 <code>CC</code> 或 <code>CACHE</code>，请删除这两个参数。这两个参数的功能已经分别移动进了指令 <code>waf_cc_deny</code> 和 <code>waf_cache</code>。</li><li>如果你想开启 CC 防护，请修改指令 <code>waf_cc_deny</code> 的参数，例如将 <code>waf_cc_deny rate=2000r/m duration=1h</code> 改为 <code>waf_cc_deny on rate=2000r/m duration=1h</code>。</li><li>如果你想开启缓存，请修改指令 <code>waf_cache</code> 的参数，例如将 <code>waf_cache capacity=50</code> 改为 <code>waf_cache on capacity=50</code>。</li><li>如果你在 <code>http</code> 块中使用了指令 <code>waf_cc_deny</code> 或 <code>waf_cache</code>，请将这两个指令移动到更内层。</li><li>如果你使用了指令 <code>waf_cache</code> 并且使用了该指令的参数 <code>interval</code> 或 <code>percent</code>，请删除这两个参数，这两个参数已经被移除。</li><li>如果你使用了指令 <code>waf_priority</code>，请将 <code>VERIFY-BOT</code> 和 <code>CAPTCHA</code> 添加进去。</li></ol><h2 id="从-6-x-x-升级到-7-x-x" tabindex="-1">从 <code>6.x.x</code> 升级到 <code>7.x.x</code> <a class="header-anchor" href="#从-6-x-x-升级到-7-x-x" aria-label="Permalink to &quot;从 `6.x.x` 升级到 `7.x.x`&quot;">​</a></h2><ol><li>如果你在 <code>http</code> 块中使用了指令 <code>waf_cc_deny</code>，请将这个指令移动到更内层。</li></ol><h2 id="从-5-x-x-升级到-6-x-x" tabindex="-1">从 <code>5.x.x</code> 升级到 <code>6.x.x</code> <a class="header-anchor" href="#从-5-x-x-升级到-6-x-x" aria-label="Permalink to &quot;从 `5.x.x` 升级到 `6.x.x`&quot;">​</a></h2><ol><li>在规则目录下新建一个名为 <code>advanced</code> 的空文件。</li><li>如果使用了配置项 <code>waf_priority</code>，可以将其删除或者按照文档中对该配置项的说明进行修改。</li></ol>',12)])])}const f=c(l,[["render",i]]);export{s as __pageData,f as default};
